import base64, hashlib, hmac, json, os, secrets, time
from fastapi import Depends, HTTPException
from fastapi.security import HTTPAuthorizationCredentials, HTTPBearer
bearer=HTTPBearer(auto_error=False)

def secret():
    value=os.getenv('AUTH_SECRET','')
    if len(value)<32: raise HTTPException(503,'Configure AUTH_SECRET com pelo menos 32 caracteres')
    return value.encode()
def users():
    # Store only salted PBKDF2 digests generated by scripts/init_demo.py.
    from pathlib import Path
    path=Path(os.getenv('DEMO_USERS_FILE','app/data/demo_users.json'))
    if not path.exists(): raise HTTPException(503,'Execute scripts/init_demo.py')
    return json.loads(path.read_text(encoding="utf-8"))
def password_hash(password,salt):
    return hashlib.pbkdf2_hmac('sha256',password.encode(),bytes.fromhex(salt),200000).hex()
def login(username,password):
    u=users().get(username)
    salt=u['salt'] if u else '00'*16
    digest=password_hash(password,salt)
    if not u or not hmac.compare_digest(digest,u['hash']): raise HTTPException(401,'Credenciais inválidas')
    body=base64.urlsafe_b64encode(json.dumps({'sub':username,'role':u['role'],'exp':int(time.time())+3600}).encode()).decode()
    sig=hmac.new(secret(),body.encode(),hashlib.sha256).hexdigest()
    return {'access_token':body+'.'+sig,'token_type':'bearer','role':u['role']}
def identity(credentials: HTTPAuthorizationCredentials=Depends(bearer)):
    if not credentials: raise HTTPException(401,'Autenticação obrigatória')
    try:
        body,sig=credentials.credentials.split('.')
        if not hmac.compare_digest(hmac.new(secret(),body.encode(),hashlib.sha256).hexdigest(),sig): raise ValueError()
        claim=json.loads(base64.urlsafe_b64decode(body))
        if claim['exp']<=time.time() or claim['role'] not in ('customer','operator','admin'): raise ValueError()
        current=users().get(claim['sub'])
        if not current or current['role']!=claim['role']: raise ValueError()
        return claim
    except (ValueError,KeyError,TypeError): raise HTTPException(401,'Token inválido ou expirado')
def customer(who=Depends(identity)):
    if who['role']!='customer': raise HTTPException(403,'Somente cliente')
    return who
